INSERT INTO `wp_options` VALUES (321,'_site_transient_wp_plugin_dependencies_plugin_data','a:1:{s:14:\"contact-form-7\";a:35:{s:4:\"name\";s:14:\"Contact Form 7\";s:4:\"slug\";s:14:\"contact-form-7\";s:7:\"version\";s:5:\"6.1.6\";s:6:\"author\";s:78:\"<a href=\"https://profiles.wordpress.org/rocklobsterinc/\">Rock Lobster Inc.</a>\";s:14:\"author_profile\";s:46:\"https://profiles.wordpress.org/rocklobsterinc/\";s:12:\"contributors\";a:2:{s:14:\"rocklobsterinc\";a:3:{s:7:\"profile\";s:46:\"https://profiles.wordpress.org/rocklobsterinc/\";s:6:\"avatar\";s:120:\"https://secure.gravatar.com/avatar/4aa558df1c07e327536d8d0adad6d00fcdca0484c51adf0b867a2aa5ee054bbc?s=96&d=monsterid&r=g\";s:12:\"display_name\";s:17:\"Rock Lobster Inc.\";}s:12:\"takayukister\";a:3:{s:7:\"profile\";s:44:\"https://profiles.wordpress.org/takayukister/\";s:6:\"avatar\";s:120:\"https://secure.gravatar.com/avatar/538487024e649d43dea84ff38d14582d03119e3e7aaaca3b7692443335999133?s=96&d=monsterid&r=g\";s:12:\"display_name\";s:16:\"Takayuki Miyoshi\";}}s:8:\"requires\";s:3:\"6.7\";s:6:\"tested\";s:3:\"7.0\";s:12:\"requires_php\";s:3:\"7.4\";s:16:\"requires_plugins\";a:0:{}s:6:\"rating\";i:80;s:7:\"ratings\";a:5:{i:5;i:1468;i:4;i:157;i:3;i:78;i:2;i:68;i:1;i:404;}s:11:\"num_ratings\";i:2175;s:11:\"support_url\";s:52:\"https://wordpress.org/support/plugin/contact-form-7/\";s:15:\"support_threads\";i:78;s:24:\"support_threads_resolved\";i:29;s:15:\"active_installs\";i:10000000;s:12:\"last_updated\";s:21:\"2026-05-15 2:55am GMT\";s:5:\"added\";s:10:\"2007-08-02\";s:8:\"homepage\";s:25:\"https://contactform7.com/\";s:8:\"sections\";a:6:{s:11:\"description\";s:2525:\"<p>Contact Form 7 is a plugin designed to be a practical tool for all WordPress users who embrace the philosophy of free and open source software. It employs sophisticatedly modularized architecture and its original <a href=\"https://contactform7.com/schema-woven-validation/\" rel=\"nofollow ugc\">Schema-Woven Validation</a> technology.</p>\n<h4>Docs and support</h4>\n<p>You can find <a href=\"https://contactform7.com/docs/\" rel=\"nofollow ugc\">docs</a>, <a href=\"https://contactform7.com/faq/\" rel=\"nofollow ugc\">FAQ</a> and more detailed information about Contact Form 7 on <a href=\"https://contactform7.com/\" rel=\"nofollow ugc\">contactform7.com</a>. When you cannot find the answer to your question on the FAQ or in any of the documentation, check the <a href=\"https://wordpress.org/support/plugin/contact-form-7/\" rel=\"ugc\">support forum</a> on WordPress.org. If you cannot locate any topics that pertain to your particular issue, post a new topic for it.</p>\n<h4>Contact Form 7 needs your support</h4>\n<p>It is hard to continue to maintain this plugin without support from users like you. There are several ways for you to <a href=\"https://contactform7.com/contributing/\" rel=\"nofollow ugc\">contribute to the project</a>: testing, coding, translating it into your local languages, helping other users, financial donations, etc, etc. We equally welcome you regardless of the way you contribute.</p>\n<h4>Privacy notices</h4>\n<p>With the default configuration, this plugin, in itself, does not:</p>\n<ul>\n<li>track users by stealth;</li>\n<li>write any user personal data to the database;</li>\n<li>send any data to external servers;</li>\n<li>use cookies.</li>\n</ul>\n<p>If you activate certain features in this plugin, the contact form submitter&#8217;s personal data, including their IP address, may be sent to the service provider. Thus, confirming the provider&#8217;s privacy policy is recommended. These features include:</p>\n<ul>\n<li>reCAPTCHA (<a href=\"https://policies.google.com/?hl=en\" rel=\"nofollow ugc\">Google</a>)</li>\n<li>Akismet (<a href=\"https://automattic.com/privacy/\" rel=\"nofollow ugc\">Automattic</a>)</li>\n<li><a href=\"https://www.constantcontact.com/legal/privacy-center\" rel=\"nofollow ugc\">Constant Contact</a></li>\n<li><a href=\"https://www.brevo.com/legal/privacypolicy/\" rel=\"nofollow ugc\">Brevo</a></li>\n<li><a href=\"https://stripe.com/privacy\" rel=\"nofollow ugc\">Stripe</a></li>\n<li>Turnstile (<a href=\"https://www.cloudflare.com/turnstile-privacy-policy/\" rel=\"nofollow ugc\">Cloudflare</a>)</li>\n</ul>\n\";s:12:\"installation\";s:458:\"<ol>\n<li>Upload the entire <code>contact-form-7</code> folder to the <code>/wp-content/plugins/</code> directory.</li>\n<li>Activate the plugin through the <strong>Plugins</strong> screen (<strong>Plugins &gt; Installed Plugins</strong>).</li>\n</ol>\n<p>You will find <strong>Contact</strong> menu in your WordPress admin screen.</p>\n<p>For basic usage, have a look at the <a href=\"https://contactform7.com/\" rel=\"nofollow ugc\">plugin&#8217;s website</a>.</p>\n\";s:3:\"faq\";s:449:\"<p>Do you have questions or issues with Contact Form 7? Use these support channels appropriately.</p>\n<ol>\n<li><a href=\"https://contactform7.com/docs/\" rel=\"nofollow ugc\">Docs</a></li>\n<li><a href=\"https://contactform7.com/faq/\" rel=\"nofollow ugc\">FAQ</a></li>\n<li><a href=\"https://wordpress.org/support/plugin/contact-form-7/\" rel=\"ugc\">Support forum</a></li>\n</ol>\n<p><a href=\"https://contactform7.com/support/\" rel=\"nofollow ugc\">Support</a></p>\n\";s:9:\"changelog\";s:2061:\"<p>For more information, see <a href=\"https://contactform7.com/category/releases/\" rel=\"nofollow ugc\">Releases</a>.</p>\n<h4>6.1.6</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-616/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-616/</a></p>\n<h4>6.1.5</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-615/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-615/</a></p>\n<h4>6.1.4</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-614/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-614/</a></p>\n<h4>6.1.3</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-613/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-613/</a></p>\n<h4>6.1.2</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-612/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-612/</a></p>\n<h4>6.1.1</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-611/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-611/</a></p>\n<h4>6.1</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-61/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-61/</a></p>\n<h4>6.0.5</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-605/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-605/</a></p>\n<h4>6.0.4</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-604/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-604/</a></p>\n<h4>6.0.3</h4>\n<ul>\n<li>Updates the copyright year to 2025.</li>\n<li>Updates the &#8220;Contact Form 7 needs your support&#8221; message content.</li>\n<li>Updates the Constant Contact deprecation warning.</li>\n</ul>\n<h4>6.0.2</h4>\n<ul>\n<li>Removes unnecessary type declaration from nullable arguments to avoid deprecation warnings in PHP 8.4.</li>\n</ul>\n<h4>6.0.1</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-601/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-601/</a></p>\n<h4>6.0</h4>\n<p><a href=\"https://contactform7.com/contact-form-7-60/\" rel=\"nofollow ugc\">https://contactform7.com/contact-form-7-60/</a></p>\n\";s:11:\"screenshots\";s:225:\"<ol><li><a href=\"https://ps.w.org/contact-form-7/assets/screenshot-1.png?rev=1176454\"><img src=\"https://ps.w.org/contact-form-7/assets/screenshot-1.png?rev=1176454\" alt=\"screenshot-1.png\"></a><p>screenshot-1.png</p></li></ol>\";s:7:\"reviews\";s:15373:\"<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Old School But Works</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"4 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"4\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-empty\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/alenaalan/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/5774e9237df2d682251b5bb68ce3c0d0e676757b184baaf77ae287f7d8fd4122?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/5774e9237df2d682251b5bb68ce3c0d0e676757b184baaf77ae287f7d8fd4122?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/alenaalan/\" class=\"reviewer-name\">alenaalan</a> on <span class=\"review-date\">May 25, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>Looks outdated ngl bt does exactly wht u need. Set up a working form in like 5 mins. Had 2 install a sep captcha plugin 4 spam tho. Still using it on every client site I build lol</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Works But Plain</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"4 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"4\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-empty\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/mary944/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/a08b4eab0cb826b249ffb612dd828fb83e4b6e62d1306048deb8dd07603656fc?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/a08b4eab0cb826b249ffb612dd828fb83e4b6e62d1306048deb8dd07603656fc?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/mary944/\" class=\"reviewer-name\">mary944</a> on <span class=\"review-date\">May 21, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>gets emails to me just fine. setup was confusing at first ngl. no drag n drop builder which kinda sucks. spam can be an issue sometimes. still using it tho, does what it says</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Just Use It</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"5 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"5\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/kaiasteffen/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/304cc2390b36443047cac9642cc98dfdcca9085ae8438af88f637647a1e4e564?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/304cc2390b36443047cac9642cc98dfdcca9085ae8438af88f637647a1e4e564?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/kaiasteffen/\" class=\"reviewer-name\">kaiasteffen</a> on <span class=\"review-date\">May 18, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>y r u even reading this lol just install it. free, lightweight &amp; gets the job done. my contact page has been running smooth 4 months w zero problems</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Solid Free Plugin</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"4 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"4\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-empty\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/adina89/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/148c03489f9a7a4efab411cf292b5e614c6a29c52a92fcbe50bf68ed3aa4e432?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/148c03489f9a7a4efab411cf292b5e614c6a29c52a92fcbe50bf68ed3aa4e432?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/adina89/\" class=\"reviewer-name\">adina89</a> on <span class=\"review-date\">May 15, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>been using CF7 for months now, no issues at all! forms load fast n submissions come thru instantly styling cud be better cz it looks rly basic. bt hey it wrks, n thts wt matters</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Simple &amp; Reliable</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"4 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"4\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-empty\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/houston2/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/844515f75003264eef7188a5ecfdea9295e0c3d1196040eb9e0ba51202a3b8c2?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/844515f75003264eef7188a5ecfdea9295e0c3d1196040eb9e0ba51202a3b8c2?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/houston2/\" class=\"reviewer-name\">houston2</a> on <span class=\"review-date\">May 13, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>Does wat it says. Got my form running in mins, zero coding needed. Styling options r a bit basic bt hey, it works perfectly fine. Solid free plugin, tnkz devs</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Old but gold</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"5 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"5\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/alexa793/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/586b80f3f4b49d81cb1894550eb75a7fa5a8e6a90f85325b22b249dffcc578e5?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/586b80f3f4b49d81cb1894550eb75a7fa5a8e6a90f85325b22b249dffcc578e5?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/alexa793/\" class=\"reviewer-name\">alexa793</a> on <span class=\"review-date\">May 12, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>bin using this 4ever. Setup is so basic. Just paste the shortcode and u get a working form fast. No heavy stuff bcz it handles msgs perfectly for free. saved me a ton of headache. ty</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Hard to style</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"3 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"3\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-empty\"></span><span class=\"star dashicons dashicons-star-empty\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/longcrocker/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/080977ad3f7b82ea2e4015658ca78c22e50332cbb1a00cd7e8323f7675045efc?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/080977ad3f7b82ea2e4015658ca78c22e50332cbb1a00cd7e8323f7675045efc?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/longcrocker/\" class=\"reviewer-name\">longcrocker</a> on <span class=\"review-date\">May 11, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>Tnx for making it free! It helped me get msgs from users fast. But the setup is a bit confusing cz there\'s no drag &amp; drop. Good enough if u know basic code, otherwise kinda tricky.</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Just works perfectly</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"5 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"5\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/raheembrittain/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/838b716de56c3ba61e150d1ff88f24a38a41a8f185c223849cada5c5d73e30af?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/838b716de56c3ba61e150d1ff88f24a38a41a8f185c223849cada5c5d73e30af?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/raheembrittain/\" class=\"reviewer-name\">raheembrittain</a> on <span class=\"review-date\">May 7, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>Been using this 4ever. Super simple to get a basic contact form up fast. Never misses an email which is huge for my biz. Tysm for this free gem!</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Works Pretty Well</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"4 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"4\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-empty\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/janice87/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/223552bc4e02cae1ae78ec71cf262909f5602e029957f7a51cab0ca6076fffa4?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/223552bc4e02cae1ae78ec71cf262909f5602e029957f7a51cab0ca6076fffa4?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/janice87/\" class=\"reviewer-name\">janice87</a> on <span class=\"review-date\">May 4, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>Good for simple contact forms. Setup was not hard and mails came through fine. I just wish the settings looked more modern. Still a solid plugin. tnkz</p>\n<!-- /wp:paragraph --></div>\n</div>\n<div class=\"review\">\n	<div class=\"review-head\">\n		<div class=\"reviewer-info\">\n			<div class=\"review-title-section\">\n				<h4 class=\"review-title\">Still Reliable</h4>\n				<div class=\"star-rating\">\n				<div class=\"wporg-ratings\" aria-label=\"5 out of 5 stars\" data-title-template=\"%s out of 5 stars\" data-rating=\"5\" style=\"color:#ffb900;\"><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span><span class=\"star dashicons dashicons-star-filled\"></span></div>				</div>\n			</div>\n			<p class=\"reviewer\">\n				By <a href=\"https://profiles.wordpress.org/anjali00/\"><img alt=\'\' src=\'https://secure.gravatar.com/avatar/4f88be3f0e02aa7d28ff5db1c8acd667b39c1c9d2243d6d62ba4ae37be5a0d1f?s=16&#038;d=monsterid&#038;r=g\' srcset=\'https://secure.gravatar.com/avatar/4f88be3f0e02aa7d28ff5db1c8acd667b39c1c9d2243d6d62ba4ae37be5a0d1f?s=32&#038;d=monsterid&#038;r=g 2x\' class=\'avatar avatar-16 photo\' height=\'16\' width=\'16\' loading=\'lazy\' decoding=\'async\'/></a><a href=\"https://profiles.wordpress.org/anjali00/\" class=\"reviewer-name\">anjali00</a> on <span class=\"review-date\">April 30, 2026</span>			</p>\n		</div>\n	</div>\n	<div class=\"review-body\"><!-- wp:paragraph -->\n<p>No fancy drama, it just does the job. I added a contact form quickly and it started working fine. Simple, light, and useful for regular sites. tnkz</p>\n<!-- /wp:paragraph --></div>\n</div>\n\";}s:17:\"short_description\";s:54:\"Just another contact form plugin. Simple but flexible.\";s:13:\"download_link\";s:63:\"https://downloads.wordpress.org/pl